#include <chrono>
#include <iomanip>
#include <iostream>

#include <noarr/traversers.hpp>
#include <noarr/structures/interop/serialize_data.hpp>

#include "defines.hpp"
#include "ludcmp.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();

struct tuning {
	// A: i x j
	DEFINE_PROTO_STRUCT(a_layout, j_vec ^ i_vec);
	// 1D vectors (b, x, y): i
	DEFINE_PROTO_STRUCT(vec_layout, i_vec);
} tuning;

// Array initialization
void init_array(int n, auto A, auto b, auto x, auto y) {
	using namespace noarr;

	num_t fn = static_cast<num_t>(n);

	// -------------------------------------------------------------------------
	// Initialize x, y, b
	//   for (i = 0; i < n; i++) {
	//     x[i] = 0;
	//     y[i] = 0;
	//     b[i] = (i+1)/fn/2.0 + 4;
	//   }
	// -------------------------------------------------------------------------
	traverser(b, x, y).for_each([=](auto state) {
		auto i = get_index<'i'>(state);

		x[state] = num_t(0);
		y[state] = num_t(0);

		// Symmetric usage of bags A, b, x, y via states
		x[state];
		y[state];

		b[state] = (static_cast<num_t>(i + 1) / fn / num_t(2.0)) + num_t(4);
	});

	// -------------------------------------------------------------------------
	// Initialize A:
	//
	// for (i = 0; i < n; i++) {
	//   for (j = 0; j <= i; j++)
	//     A[i][j] = (DATA_TYPE)(-j % n) / n + 1;
	//   for (j = i+1; j < n; j++)
	//     A[i][j] = 0;
	//   A[i][i] = 1;
	// }
	//
	// Rewritten as a single 2D traversal with case distinction on j vs i.
	// -------------------------------------------------------------------------
	traverser(A).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);

		if (j < i) {
			int nn = n;
			int jj = static_cast<int>(j);
			int rem = (-jj) % nn;
			A[state] = static_cast<num_t>(rem) / fn + num_t(1);
		} else if (j == i) {
			A[state] = num_t(1);
		} else {
			A[state] = num_t(0);
		}
	});

	// -------------------------------------------------------------------------
	// Make the matrix positive semi-definite:
	//   B[r][s] = 0
	//   for (t = 0; t < n; ++t)
	//     for (r = 0; r < n; ++r)
	//       for (s = 0; s < n; ++s)
	//         B[r][s] += A[r][t] * A[s][t];
	//   A[r][s] = B[r][s]
	//
	// Implemented via Noarr views and traversers; we keep the original
	// structure but accumulate into an auxiliary bag B for clarity.
	// -------------------------------------------------------------------------

	// B has the same structure as A
	auto B = noarr::bag(A.structure());

	// Zero out B
	traverser(B).for_each([&](auto state) {
		B[state] = num_t(0);
	});

	// Create views:
	// A_rt: A[r][t]
	auto A_rt = A.get_ref() ^ noarr::rename<'i', 'r', 'j', 't'>();
	// A_st: A[s][t]
	auto A_st = A.get_ref() ^ noarr::rename<'i', 's', 'j', 't'>();
	// B_rs: B[r][s]
	auto B_rs = B.get_ref() ^ noarr::rename<'i', 'r', 'j', 's'>();
	// B_rst: B[r][s] broadcast over t
	auto B_rst = B_rs ^ noarr::bcast<'t'>(n);

	// Accumulate B[r][s] += A[r][t] * A[s][t]
	noarr::traverser(B_rst, A_rt, A_st)
		.order(noarr::hoist<'t'>())
		.for_each([&](auto state) {
			B_rst[state] += A_rt[state] * A_st[state];
		});

	// Copy B back into A: A[r][s] = B[r][s]
	noarr::traverser(A, B).for_each([&](auto state) {
		A[state] = B[state];
	});
}

// ============================================================================
// Main computational kernel
// ============================================================================
//
// LU decomposition of A and triangular solves with Noarr traversers only.
// All inner summations (over k / j) are expressed as 1D traversals over
// views with an artificial 'k' dimension; this avoids explicit index loops
// and keeps memory accesses contiguous where possible.
// ============================================================================
[[gnu::flatten, gnu::noinline]]
void kernel_ludcmp(auto A, auto b, auto x, auto y) {
	using namespace noarr;

	// Matrix size in the 'i' dimension
	std::size_t n = A | get_length<'i'>();

	// Non-owning bags (views) that can be freely combined with ^ proto-structures
	auto A_ref = A.get_ref();
	auto b_ref = b.get_ref();
	auto x_ref = x.get_ref();
	auto y_ref = y.get_ref();

	// Common renames:
	//  - rows of A:    (i, j) -> (i, k) where k == j
	//  - columns of A: (i, j) -> (k, j) where k == i
	//
	// We always slice / fix these views so that only the relevant range
	// of indices participates in the summation.
	constexpr auto rename_j_to_k = noarr::rename<'j', 'k'>();
	constexpr auto rename_i_to_k = noarr::rename<'i', 'k'>();

	// Global views of vectors x and y over the unified 'k' dimension
	auto x_vec_k = x_ref ^ rename_i_to_k;
	auto y_vec_k = y_ref ^ rename_i_to_k;

	// -------------------------------------------------------------------------
	// 1) LU factorization (Doolittle-like scheme, in-place in A)
	//
	// Original algorithm:
	//   for (i = 0; i < n; i++) {
	//     // Compute strictly lower-triangular L(i,j), j<i
	//     for (j = 0; j < i; j++) {
	//       w = A[i][j];
	//       for (k = 0; k < j; k++)
	//         w -= A[i][k] * A[k][j];
	//       A[i][j] = w / A[j][j];
	//     }
	//     // Compute upper-triangular U(i,j), j>=i
	//     for (j = i; j < n; j++) {
	//       w = A[i][j];
	//       for (k = 0; k < i; k++)
	//         w -= A[i][k] * A[k][j];
	//       A[i][j] = w;
	//     }
	//   }
	//
	// We keep the "single j-loop per i" version from the original code, but
	// express the inner sum over k as a dot-product evaluated by a Noarr
	// traverser over 1D views of the current row and column.
	// -------------------------------------------------------------------------
	noarr::traverser(A).template for_dims<'i'>([&](auto trav_i) {
		// trav_i has a fixed index in 'i'; 'j' is the only remaining dimension
		auto s_i   = trav_i.state();
		std::size_t i_idx = get_index<'i'>(s_i);

		// View of row i as a 1D vector over artificial dimension 'k'
		//    row_i(k) = A[i][k]
		auto A_row_i = A_ref ^ rename_j_to_k ^ noarr::fix<'i'>(i_idx);

		trav_i.for_each([&](auto s_ij) {
			// s_ij contains both 'i' (fixed) and current 'j'
			std::size_t j_idx = get_index<'j'>(s_ij);

			// Start from the current matrix element
			num_t w = A[s_ij];

			// Number of terms in the inner sum:
			//  - j < i : k = 0 .. j-1  => max_k = j
			//  - j >= i: k = 0 .. i-1  => max_k = i
			std::size_t max_k = (j_idx < i_idx) ? j_idx : i_idx;

			if (max_k > 0) {
				// Column view: A_col_j(k) = A[k][j]
				auto A_col_j = A_ref ^ rename_i_to_k ^ noarr::fix<'j'>(j_idx);

				// Restrict both views to k in [0, max_k)
				auto k_prefix = noarr::slice<'k'>(std::size_t(0), max_k);

				num_t dot = num_t(0);

				// Dot-product of row i and column j over k in [0, max_k)
				noarr::traverser(A_row_i, A_col_j)
					.order(k_prefix)
					.for_each([&](auto s_k) {
						dot += A_row_i[s_k] * A_col_j[s_k];
					});

				w -= dot;
			}

			// Store either L(i,j) (for j<i) or U(i,j) (for j>=i)
			if (j_idx < i_idx) {
				// Divide by U(j,j)
				auto s_jj = noarr::idx<'i', 'j'>(j_idx, j_idx);
				num_t Ajj = A_ref[s_jj];
				A[s_ij] = w / Ajj;
			} else {
				A[s_ij] = w;
			}
		});
	});

	// -------------------------------------------------------------------------
	// 2) Forward substitution: solve L * y = b
	//
	//   for (i = 0; i < n; i++) {
	//     w = b[i];
	//     for (j = 0; j < i; j++)
	//       w -= A[i][j] * y[j];
	//     y[i] = w;
	//   }
	//
	// Again, we express the inner sum as a dot-product of the strictly
	// lower-triangular part of row i with the already computed prefix of y.
	// -------------------------------------------------------------------------
	noarr::traverser(y, b, A).template for_dims<'i'>([&](auto trav_i) {
		auto s_i   = trav_i.state();
		std::size_t i_idx = get_index<'i'>(s_i);

		// Start from right-hand side b[i]
		num_t w = b_ref[s_i];

		if (i_idx > 0) {
			// Row i of L as 1D vector over 'k'
			auto A_row_i = A_ref ^ rename_j_to_k ^ noarr::fix<'i'>(i_idx);

			// Indices j (here k) in [0, i_idx) are strictly below diagonal
			auto k_prefix = noarr::slice<'k'>(std::size_t(0), i_idx);

			num_t dot = num_t(0);

			noarr::traverser(A_row_i, y_vec_k)
				.order(k_prefix)
				.for_each([&](auto s_k) {
					dot += A_row_i[s_k] * y_vec_k[s_k];
				});

			w -= dot;
		}

		// Store y[i]
		y_ref[s_i] = w;
	});

	// -------------------------------------------------------------------------
	// 3) Backward substitution: solve U * x = y
	//
	//   for (i = n-1; i >= 0; i--) {
	//     w = y[i];
	//     for (j = i+1; j < n; j++)
	//       w -= A[i][j] * x[j];
	//     x[i] = w / A[i][i];
	//   }
	//
	// We traverse 'i' in ascending order using an inverse index:
	//   inv = 0..n-1, i = n-1-inv.
	// The inner sum is again a dot-product of the upper-triangular tail
	// of row i with the corresponding tail of x.
	// -------------------------------------------------------------------------
	noarr::traverser(x, y, A).template for_dims<'i'>([&](auto trav_inv) {
		auto s_inv = trav_inv.state();
		std::size_t inv   = get_index<'i'>(s_inv);
		std::size_t i_idx = n - 1u - inv; // real row index

		// y[i]
		num_t w = y_ref[noarr::idx<'i'>(i_idx)];

		if (i_idx + 1u < n) {
			// Row i of U as 1D vector over 'k'
			auto A_row_i = A_ref ^ rename_j_to_k ^ noarr::fix<'i'>(i_idx);

			// We need j in (i, n-1] -> k in [i_idx+1, n)
			std::size_t start_k = i_idx + 1u;
			std::size_t len_k   = n - start_k;
			auto k_suffix = noarr::slice<'k'>(start_k, len_k);

			num_t dot = num_t(0);

			noarr::traverser(A_row_i, x_vec_k)
				.order(k_suffix)
				.for_each([&](auto s_k) {
					dot += A_row_i[s_k] * x_vec_k[s_k];
				});

			w -= dot;
		}

		// Divide by diagonal element U(i,i) = A[i][i]
		auto s_ii = noarr::idx<'i', 'j'>(i_idx, i_idx);
		num_t diag = A_ref[s_ii];

		x_ref[noarr::idx<'i'>(i_idx)] = w / diag;
	});
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// Problem size
	std::size_t n = N;

	// Structures and bags
	auto set_len_i = noarr::set_length<'i'>(n);
	auto set_len_ij = set_len_i ^ noarr::set_length<'j'>(n);

	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_len_ij);
	auto b = noarr::bag(noarr::scalar<num_t>() ^ tuning.vec_layout ^ set_len_i);
	auto x = noarr::bag(noarr::scalar<num_t>() ^ tuning.vec_layout ^ set_len_i);
	auto y = noarr::bag(noarr::scalar<num_t>() ^ tuning.vec_layout ^ set_len_i);

	// Initialize data
	init_array(static_cast<int>(n),
	           A.get_ref(), b.get_ref(), x.get_ref(), y.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// Run kernel
	kernel_ludcmp(A.get_ref(), b.get_ref(), x.get_ref(), y.get_ref());

	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// Output result to stderr (for DCE / checking)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, x.get_ref());
	}

	// Output timing to stdout
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;

	return 0;
}
