#include <chrono>
#include <iomanip>
#include <iostream>

#include <noarr/structures_extended.hpp> // for fix, slice, rename, bcast, hoist, bag, ...
#include <noarr/traversers.hpp>
#include <noarr/structures/interop/serialize_data.hpp>

#include "defines.hpp"
#include "ludcmp.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();

struct tuning {
	// A: i x j
	//
	// Original code used `j_vec ^ i_vec`, which makes 'i' the inner (fast) dimension
	// and 'j' the outer one. The main kernel traverses with 'i' outer and 'j' inner,
	// therefore accesses had poor spatial locality.
	//
	// Here we switch to `i_vec ^ j_vec`, which makes 'j' the inner (contiguous)
	// dimension. This aligns the memory layout with the traversal order in the LU
	// kernel and improves cache efficiency without changing the mathematical result.
	DEFINE_PROTO_STRUCT(a_layout, i_vec ^ j_vec);

	// 1D vectors (b, x, y): i
	DEFINE_PROTO_STRUCT(vec_layout, i_vec);
} tuning;


// Array initialization
void init_array(int n, auto A, auto b, auto x, auto y) {
	using namespace noarr;

	num_t fn = static_cast<num_t>(n);

	// -------------------------------------------------------------------------
	// Initialize x, y, b
	//
	// for (i = 0; i < n; i++) {
	//   x[i] = 0;
	//   y[i] = 0;
	//   b[i] = (i+1)/fn/2.0 + 4;
	// }
	// -------------------------------------------------------------------------
	traverser(b, x, y).for_each([=](auto state) {
		auto i = get_index<'i'>(state);

		x[state] = num_t(0);
		y[state] = num_t(0);

		// keep structure usage symmetrical (touch both x and y via the same state)
		x[state];
		y[state];

		b[state] = (static_cast<num_t>(i + 1) / fn / num_t(2.0)) + num_t(4);
	});

	// -------------------------------------------------------------------------
	// Initialize A:
	//
	// for (i = 0; i < n; i++) {
	//   for (j = 0; j <= i; j++)
	//     A[i][j] = (DATA_TYPE)(-j % n) / n + 1;
	//   for (j = i+1; j < n; j++)
	//     A[i][j] = 0;
	//   A[i][i] = 1;
	// }
	//
	// Rewritten as a single 2D traversal with case distinction on j vs i.
	// -------------------------------------------------------------------------
	traverser(A).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);

		if (j < i) {
			// (DATA_TYPE)(-j % n) / n + 1;
			int nn = n;
			int jj = static_cast<int>(j);
			int rem = (-jj) % nn;
			A[state] = static_cast<num_t>(rem) / fn + num_t(1);
		} else if (j == i) {
			A[state] = num_t(1);
		} else {
			A[state] = num_t(0);
		}
	});

	// -------------------------------------------------------------------------
	// Make the matrix positive semi-definite:
	//
	// B[r][s] = 0
	// for (t = 0; t < n; ++t)
	//   for (r = 0; r < n; ++r)
	//     for (s = 0; s < n; ++s)
	//       B[r][s] += A[r][t] * A[s][t];
	// A[r][s] = B[r][s]
	//
	// Implemented using views and a single traverser. We keep the accumulation
	// order in 't' untouched to preserve floating-point semantics.
	// -------------------------------------------------------------------------

	// B has the same structure as A
	auto B = noarr::bag(A.structure());

	// Zero out B
	traverser(B).for_each([&](auto state) {
		B[state] = num_t(0);
	});

	// Create views:
	// A_rt: A[r][t]
	auto A_rt = A.get_ref() ^ noarr::rename<'i', 'r', 'j', 't'>();
	// A_st: A[s][t]
	auto A_st = A.get_ref() ^ noarr::rename<'i', 's', 'j', 't'>();
	// B_rs: B[r][s]
	auto B_rs = B.get_ref() ^ noarr::rename<'i', 'r', 'j', 's'>();
	// B_rst: B[r][s] broadcast over t
	auto B_rst = B_rs ^ noarr::bcast<'t'>(n);

	// Accumulate B[r][s] += A[r][t] * A[s][t]
	//
	// `hoist<'t'>` makes 't' the outermost loop, so each B[r][s] is updated
	// in the same order of t as in the scalar triple loop above.
	noarr::traverser(B_rst, A_rt, A_st)
		.order(noarr::hoist<'t'>())
		.for_each([&](auto state) {
			B_rst[state] += A_rt[state] * A_st[state];
		});

	// Copy B back into A: A[r][s] = B[r][s]
	noarr::traverser(A, B).for_each([&](auto state) {
		A[state] = B[state];
	});
}


// Main computational kernel
//
// The implementation below closely follows the standard Doolittle LU
// factorization and the subsequent forward and backward substitutions, but it
// is written using Noarr traversers and simple one-dimensional scalar loops
// for the innermost accumulation over k. The latter combines a row and a
// column of A and is not naturally a single Noarr dimension; representing it
// with a traverser would require repeated construction of transient views and
// be more costly than a tight scalar loop.
//
// We separate the lower (L) and upper (U) part work in j, avoiding branches
// in the hot loops and using Noarr `slice` to limit the j‑ranges. We also
// create per-row views (`fix<'i'>`) to improve locality for repeated access
// to A[i][*].
//
// All arithmetic for a given element A[i][j] is performed in exactly the same
// order as in the original code; only the traversal over different j values
// is reorganized. Because elements for different j are independent, this
// reordering does not change the computed values.
//
[[gnu::flatten, gnu::noinline]]
void kernel_ludcmp(auto A, auto b, auto x, auto y) {
	using namespace noarr;

	// Length in the 'i' dimension
	std::size_t n = A | get_length<'i'>();

	// -------------------------------------------------------------------------
	// LU factorization (Doolittle-like scheme)
	//
	// Original scalar algorithm:
	// for (i = 0; i < N; i++) {
	//   for (j = 0; j < i; j++) {
	//     w = A[i][j];
	//     for (k = 0; k < j; k++)
	//       w -= A[i][k] * A[k][j];
	//     A[i][j] = w / A[j][j];
	//   }
	//   for (j = i; j < N; j++) {
	//     w = A[i][j];
	//     for (k = 0; k < i; k++)
	//       w -= A[i][k] * A[k][j];
	//     A[i][j] = w;
	//   }
	// }
	//
	// We implement this structure directly, but we:
	//  - iterate rows using a traverser over 'i'
	//  - use Noarr `slice<'j'>` to restrict j to [0,i) and [i,N)
	//  - create a row view for A[i][*] to improve cache locality
	// -------------------------------------------------------------------------
	traverser(A).template for_dims<'i'>([&](auto trav_i) {
		auto s_i = trav_i.state();
		std::size_t i_idx = get_index<'i'>(s_i);

		// View of the current row: row_i[j] == A[i_idx][j]
		auto row_i = A.get_ref() ^ fix<'i'>(i_idx);

		// --- Strict lower part: j = 0 .. i_idx-1 (L(i,j)) ---
		if (i_idx > 0) {
			// Limit traversal in 'j' to [0, i_idx)
			auto trav_L = trav_i.order(slice<'j'>(std::size_t(0), i_idx));

			trav_L.for_each([&](auto s_ij) {
				std::size_t j_idx = get_index<'j'>(s_ij);

				// w = A[i][j]
				num_t w = row_i.template at<'j'>(j_idx);

				// w -= sum_{k=0..j-1} A[i][k] * A[k][j]
				for (std::size_t k = 0; k < j_idx; ++k) {
					w -= row_i.template at<'j'>(k) *
					     A.template at<'i', 'j'>(k, j_idx);
				}

				// L(i,j) = w / A[j][j]  (stored in-place in A[i][j])
				w /= A.template at<'i', 'j'>(j_idx, j_idx);
				row_i.template at<'j'>(j_idx) = w;
			});
		}

		// --- Upper part: j = i_idx .. n-1 (U(i,j)) ---
		{
			std::size_t j_start = i_idx;
			std::size_t len = n - j_start; // at least 1

			auto trav_U = trav_i.order(slice<'j'>(j_start, len));

			trav_U.for_each([&](auto s_ij) {
				std::size_t j_idx = get_index<'j'>(s_ij);

				// w = A[i][j]
				num_t w = row_i.template at<'j'>(j_idx);

				// w -= sum_{k=0..i-1} A[i][k] * A[k][j]
				for (std::size_t k = 0; k < i_idx; ++k) {
					w -= row_i.template at<'j'>(k) *
					     A.template at<'i', 'j'>(k, j_idx);
				}

				// U(i,j) = w (stored in-place in A[i][j])
				row_i.template at<'j'>(j_idx) = w;
			});
		}
	});

	// -------------------------------------------------------------------------
	// Forward substitution: solve Ly = b
	//
	// Scalar form:
	// for (i = 0; i < N; i++) {
	//   w = b[i];
	//   for (j = 0; j < i; j++)
	//     w -= A[i][j] * y[j];
	//   y[i] = w;
	// }
	//
	// We again use a traverser over 'i' and a sliced traverser over 'j'
	// limited to [0, i), avoiding a conditional in the inner loop.
	// -------------------------------------------------------------------------
	traverser(y, b, A).template for_dims<'i'>([&](auto trav_i) {
		auto s_i = trav_i.state();
		std::size_t i_idx = get_index<'i'>(s_i);

		// View of A[i][*] for better locality
		auto row_i = A.get_ref() ^ fix<'i'>(i_idx);

		num_t w = b[s_i];

		if (i_idx > 0) {
			auto trav_j = trav_i.order(slice<'j'>(std::size_t(0), i_idx));

			trav_j.for_each([&](auto s_ij) {
				std::size_t j_idx = get_index<'j'>(s_ij);
				w -= row_i.template at<'j'>(j_idx) *
				     y.template at<'i'>(j_idx);
			});
		}

		y[s_i] = w;
	});

	// -------------------------------------------------------------------------
	// Backward substitution: solve Ux = y
	//
	// Scalar form:
	// for (i = N-1; i >= 0; i--) {
	//   w = y[i];
	//   for (j = i+1; j < N; j++)
	//     w -= A[i][j] * x[j];
	//   x[i] = w / A[i][i];
	// }
	//
	// We keep an ascending traversal over an "inverse" index:
	//   inv = 0..N-1, i = N-1-inv
	// and slice 'j' to [i+1, N), so the inner loop has no branch.
	// -------------------------------------------------------------------------
	traverser(x, y, A).template for_dims<'i'>([&](auto trav_inv) {
		auto s_inv = trav_inv.state();
		std::size_t inv = get_index<'i'>(s_inv);
		std::size_t i_idx = n - 1 - inv;

		// Row view for the current i
		auto row_i = A.get_ref() ^ fix<'i'>(i_idx);

		num_t w = y.template at<'i'>(i_idx);

		std::size_t j_start = i_idx + 1;
		if (j_start < n) {
			auto trav_j = trav_inv.order(slice<'j'>(j_start, n - j_start));

			trav_j.for_each([&](auto s_ij) {
				std::size_t j_idx = get_index<'j'>(s_ij);
				w -= row_i.template at<'j'>(j_idx) *
				     x.template at<'i'>(j_idx);
			});
		}

		x.template at<'i'>(i_idx) =
			w / row_i.template at<'j'>(i_idx);
	});
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// Problem size
	std::size_t n = N;

	// Structures and bags
	auto set_len_i = noarr::set_length<'i'>(n);
	auto set_len_ij = set_len_i ^ noarr::set_length<'j'>(n);

	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_len_ij);
	auto b = noarr::bag(noarr::scalar<num_t>() ^ tuning.vec_layout ^ set_len_i);
	auto x = noarr::bag(noarr::scalar<num_t>() ^ tuning.vec_layout ^ set_len_i);
	auto y = noarr::bag(noarr::scalar<num_t>() ^ tuning.vec_layout ^ set_len_i);

	// Initialize data
	init_array(static_cast<int>(n),
	           A.get_ref(), b.get_ref(), x.get_ref(), y.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// Run kernel
	kernel_ludcmp(A.get_ref(), b.get_ref(), x.get_ref(), y.get_ref());

	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// Output result to stderr (for DCE / checking)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, x.get_ref());
	}

	// Output timing to stdout
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;

	return 0;
}
