#include <chrono>
#include <iomanip>
#include <iostream>

#include <noarr/traversers.hpp>
#include <noarr/structures/interop/serialize_data.hpp>
#include <noarr/structures/interop/traverser_iter.hpp> // range‑based traverser iteration

#include "defines.hpp"
#include "ludcmp.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();

struct tuning {
	// A: i x j
	DEFINE_PROTO_STRUCT(a_layout, j_vec ^ i_vec);
	// 1D vectors (b, x, y): i
	DEFINE_PROTO_STRUCT(vec_layout, i_vec);
} tuning;

// -----------------------------------------------------------------------------
// Array initialization
// -----------------------------------------------------------------------------
void init_array(int n, auto A, auto b, auto x, auto y) {
	using namespace noarr;

	const num_t fn = static_cast<num_t>(n);
	const num_t inv_n = num_t(1) / fn;
	const num_t inv_2_fn = num_t(0.5) * inv_n; // 0.5 / n
	const int nn = n; // integer copy for the modulo operation

	// Initialize x, y, b
	//
	// for (i = 0; i < n; i++) {
	//   x[i] = 0;
	//   y[i] = 0;
	//   b[i] = (i+1)/fn/2.0 + 4;
	// }
	traverser(b, x, y).for_each([=](auto state) {
		auto i = get_index<'i'>(state);

		x[state] = num_t(0);
		y[state] = num_t(0);

		// (i+1)/(2*n) + 4
		b[state] = (static_cast<num_t>(i + 1) * inv_2_fn) + num_t(4);
	});

	// Initialize A:
	//
	// for (i = 0; i < n; i++) {
	//   for (j = 0; j <= i; j++)
	//     A[i][j] = (DATA_TYPE)(-j % n) / n + 1;
	//   for (j = i+1; j < n; j++)
	//     A[i][j] = 0;
	//   A[i][i] = 1;
	// }
	//
	// Rewritten as a single 2D traversal with case distinction on j vs i.
	traverser(A).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);

		if (j < i) {
			const int jj = static_cast<int>(j);
			const int rem = (-jj) % nn; // same as original
			A[state] = static_cast<num_t>(rem) * inv_n + num_t(1);
		} else if (j == i) {
			A[state] = num_t(1);
		} else {
			A[state] = num_t(0);
		}
	});

	// Make the matrix positive semi-definite:
	//
	// B[r][s] = 0
	// for (t = 0; t < n; ++t)
	//   for (r = 0; r < n; ++r)
	//     for (s = 0; s < n; ++s)
	//       B[r][s] += A[r][t] * A[s][t];
	// A[r][s] = B[r][s]

	// B has the same structure as A
	auto B = noarr::bag(A.structure());

	// Zero out B (not strictly necessary with the new formulation, but cheap
	// and keeps semantics obvious).
	traverser(B).for_each([&](auto state) {
		B[state] = num_t(0);
	});

	// Views with explicit dimension names:
	// A_rt: A[r][t]
	auto A_rt = A.get_ref() ^ noarr::rename<'i', 'r', 'j', 't'>();
	// A_st: A[s][t]
	auto A_st = A.get_ref() ^ noarr::rename<'i', 's', 'j', 't'>();
	// B_rs: B[r][s]
	auto B_rs = B.get_ref() ^ noarr::rename<'i', 'r', 'j', 's'>();

	// Compute B[r][s] = sum_t A[r][t] * A[s][t]
	//
	// We traverse B by rows ('r' outer, 's' inner) and for each pair (r,s)
	// perform a dot product over 't'. This:
	//  - keeps each B[r][s] in a register while accumulating over 't'
	//  - reuses the row view A_r across all columns s in that row
	//  - is embarrassingly parallel across rows r
	auto rows_trav = noarr::traverser(B_rs).order(noarr::hoist<'r'>());

	#pragma omp parallel for
	for (auto trav_r : rows_trav) {
		// trav_r has 'r' fixed, 's' varying
		auto state_r = trav_r.state();
		const std::size_t r = get_index<'r'>(state_r);

		// Row view A_r(t) = A[r][t]
		auto A_r = A_rt.get_ref() ^ noarr::fix<'r'>(r);

		// Iterate all columns s in this row.
		trav_r.for_each([&](auto state_rs) {
			const std::size_t s = get_index<'s'>(state_rs);

			// Row view A_s(t) = A[s][t]
			auto A_s = A_st.get_ref() ^ noarr::fix<'s'>(s);

			num_t acc = num_t(0);

			// Dot product over t: acc = sum_t A[r][t] * A[s][t]
			noarr::traverser(A_r, A_s).for_each([&](auto state_t) {
				acc += A_r[state_t] * A_s[state_t];
			});

			B_rs[state_rs] = acc;
		});
	}

	// Copy B back into A: A[r][s] = B[r][s]
	noarr::traverser(A, B).for_each([&](auto state) {
		A[state] = B[state];
	});
}

// -----------------------------------------------------------------------------
// Main computational kernel: LU decomposition + solves
// -----------------------------------------------------------------------------
[[gnu::flatten, gnu::noinline]]
void kernel_ludcmp(auto A, auto b, auto x, auto y) {
	using namespace noarr;

	// Work with non-owning bags; allows cheap creation of row/column views.
	auto A_ref = A.get_ref();
	auto b_ref = b.get_ref();
	auto x_ref = x.get_ref();
	auto y_ref = y.get_ref();

	// Length in the 'i' dimension
	const std::size_t n = A_ref | get_length<'i'>();

	// -------------------------------------------------------------------------
	// LU factorization (Doolittle-like scheme)
	//
	// Original:
	// for (i = 0; i < N; i++) {
	//   for (j = 0; j < i; j++) {
	//     w = A[i][j];
	//     for (k = 0; k < j; k++)
	//       w -= A[i][k] * A[k][j];
	//     A[i][j] = w / A[j][j];
	//   }
	//   for (j = i; j < N; j++) {
	//     w = A[i][j];
	//     for (k = 0; k < i; k++)
	//       w -= A[i][k] * A[k][j];
	//     A[i][j] = w;
	//   }
	// }
	//
	// We use a single traversal over j per i, while preserving the effective
	// loop order j = 0..N-1 and k < min(i, j). For better locality we
	// construct:
	//   - row_i(j) = A[i][j]
	//   - col_j(i) = A[i][j]
	// and use them in the inner k-loop.
	// -------------------------------------------------------------------------
	traverser(A_ref).template for_dims<'i'>([&](auto trav_i) {
		auto s_i = trav_i.state();
		const std::size_t i_idx = get_index<'i'>(s_i);

		// 1D view of row i: row_i[j] = A[i][j]
		auto row_i = A_ref ^ noarr::fix<'i'>(i_idx);

		trav_i.for_each([&](auto state_ij) {
			const std::size_t j_idx = get_index<'j'>(state_ij);

			// Start from the current value A[i][j]
			num_t w = A_ref[state_ij];

			const std::size_t max_k = (j_idx < i_idx) ? j_idx : i_idx;

			if (max_k > 0) {
				// 1D view of column j: col_j[k] = A[k][j]
				auto col_j = A_ref ^ noarr::fix<'j'>(j_idx);

				// w -= sum_{k=0..max_k-1} A[i][k] * A[k][j]
				for (std::size_t k = 0; k < max_k; ++k) {
					w -= row_i.template at<'j'>(k) *
					     col_j.template at<'i'>(k);
				}

				if (j_idx < i_idx) {
					// Lower part: divide by diagonal element A[j][j]
					w /= col_j.template at<'i'>(j_idx);
				}
			} else {
				// max_k == 0:
				//   - for j == 0 and i > 0 we still need to divide
				//     by A[0][0] in the lower part
				if (j_idx < i_idx) {
					auto col_j = A_ref ^ noarr::fix<'j'>(j_idx);
					w /= col_j.template at<'i'>(j_idx);
				}
				// for i == 0 or j >= i the normalization is skipped
			}

			A_ref[state_ij] = w;
		});
	});

	// -------------------------------------------------------------------------
	// Forward substitution: solve Ly = b  (L has unit diagonal)
	//
	// for (i = 0; i < N; i++) {
	//   w = b[i];
	//   for (j = 0; j < i; j++)
	//     w -= A[i][j] * y[j];
	//   y[i] = w;
	// }
	// -------------------------------------------------------------------------
	traverser(y_ref, b_ref, A_ref).template for_dims<'i'>([&](auto trav_i) {
		auto s_i = trav_i.state();
		const std::size_t i_idx = get_index<'i'>(s_i);

		num_t w = b_ref[s_i];

		// Row view: L(i, j) is stored in A_ref[i][j] for j < i.
		auto row_i = A_ref ^ noarr::fix<'i'>(i_idx);

		trav_i.for_each([&](auto state_ij) {
			const std::size_t j_idx = get_index<'j'>(state_ij);
			if (j_idx < i_idx) {
				w -= row_i[state_ij] * y_ref.template at<'i'>(j_idx);
			}
		});

		y_ref[s_i] = w;
	});

	// -------------------------------------------------------------------------
	// Backward substitution: solve Ux = y
	//
	// for (i = N-1; i >= 0; i--) {
	//   w = y[i];
	//   for (j = i+1; j < N; j++)
	//     w -= A[i][j] * x[j];
	//   x[i] = w / A[i][i];
	// }
	//
	// We implement this with an ascending traversal over an "inverse" index:
	//   inv = 0..N-1, i = N-1-inv
	// -------------------------------------------------------------------------
	traverser(x_ref, y_ref, A_ref).template for_dims<'i'>([&](auto trav_i) {
		auto s_inv = trav_i.state();
		const std::size_t inv = get_index<'i'>(s_inv);
		const std::size_t i_idx = n - 1 - inv;

		// Row i of U (including diagonal)
		auto row_i = A_ref ^ noarr::fix<'i'>(i_idx);

		num_t w = y_ref.template at<'i'>(i_idx);

		trav_i.for_each([&](auto state_ij) {
			const std::size_t j_idx = get_index<'j'>(state_ij);
			if (j_idx > i_idx) {
				w -= row_i.template at<'j'>(j_idx) *
				     x_ref.template at<'i'>(j_idx);
			}
		});

		x_ref.template at<'i'>(i_idx) =
			w / row_i.template at<'j'>(i_idx);
	});
}

