	// Base traverser over (r, s, t) for the A-views.
	auto trav_t_base = noarr::traverser(A_rt, A_st);

	// Triangular traversal over (r, s) with r >= s.
	noarr::traverser(B_rs).template for_dims<'r'>([&](auto trav_r) {
		auto r_state = trav_r.state();
