// Main computational kernel
[[gnu::flatten, gnu::noinline]]
void kernel_ludcmp(auto A, auto b, auto x, auto y) {
	using namespace noarr;

	// Length in the 'i' dimension (matrix is n x n)
	const std::size_t n = A | get_length<'i'>();

	// LU factorization (Doolittle-like scheme)
	//
	// Original (reference) algorithm:
	// for (i = 0; i < N; i++) {
	//   // Compute L(i, j) for j < i
	//   for (j = 0; j < i; j++) {
	//     w = A[i][j];
	//     for (k = 0; k < j; k++)
	//       w -= A[i][k] * A[k][j];
	//     A[i][j] = w / A[j][j];
	//   }
	//
	//   // Compute U(i, j) for j >= i
	//   for (j = i; j < N; j++) {
	//     w = A[i][j];
	//     for (k = 0; k < i; k++)
	//       w -= A[i][k] * A[k][j];
	//     A[i][j] = w;
	//   }
	// }
	//
	// We keep this structure, but:
	//   * use a per-row 1D view A_row_i = A[i][*] for slightly
	//     simpler address arithmetic;
	//   * use Noarr slices on 'j' to avoid inner-loop branches
	//     (no "if (j < i)" tests).

	noarr::traverser(A).template for_dims<'i'>([&](auto trav_i) {
		auto s_i = trav_i.state();
		const std::size_t i_idx = get_index<'i'>(s_i);

		// 1D view of row i: A_row_i[j] == A[i][j]
		auto A_row_i = A.get_ref() ^ noarr::fix<'i'>(i_idx);

		// --- 1) Compute L(i, j) for j < i ----------------------------------
		if (i_idx > 0) {
			// j in [0, i_idx)
			auto trav_j_lt_i = trav_i.order(noarr::slice<'j'>(0, i_idx));

			trav_j_lt_i.for_each([&](auto s_ij) {
				const std::size_t j_idx = get_index<'j'>(s_ij);

				num_t w = A[s_ij];

				// w -= sum_{k=0}^{j-1} A[i][k] * A[k][j]
				for (std::size_t k = 0; k < j_idx; ++k) {
					const num_t aik = A_row_i.template at<'j'>(k);
					const num_t akj = A.template at<'i', 'j'>(k, j_idx);
					w -= aik * akj;
				}

				const num_t ajj = A.template at<'i', 'j'>(j_idx, j_idx);
				A[s_ij] = w / ajj; // L(i,j)
			});
		}

		// --- 2) Compute U(i, j) for j >= i ---------------------------------
		{
			// j in [i_idx, n)
			auto trav_j_ge_i =
				trav_i.order(noarr::slice<'j'>(i_idx, n - i_idx));

			trav_j_ge_i.for_each([&](auto s_ij) {
				const std::size_t j_idx = get_index<'j'>(s_ij);

				num_t w = A[s_ij];

				// w -= sum_{k=0}^{i-1} A[i][k] * A[k][j]
				for (std::size_t k = 0; k < i_idx; ++k) {
					const num_t aik = A_row_i.template at<'j'>(k);
					const num_t akj = A.template at<'i', 'j'>(k, j_idx);
					w -= aik * akj;
				}

				A[s_ij] = w; // U(i,j) including the diagonal
			});
		}
	});

	// Forward substitution: solve Ly = b
	//
	// for (i = 0; i < N; i++) {
	//   w = b[i];
	//   for (j = 0; j < i; j++)
	//     w -= A[i][j] * y[j];
	//   y[i] = w;
	// }
	//
	// We again restrict j to [0, i) using a slice to avoid
	// inner-loop branches.

	noarr::traverser(y, b, A).template for_dims<'i'>([&](auto trav_i) {
		auto s_i = trav_i.state();
		const std::size_t i_idx = get_index<'i'>(s_i);

		num_t w = b[s_i];

		if (i_idx > 0) {
			auto trav_j_lt_i =
				trav_i.order(noarr::slice<'j'>(0, i_idx));

			trav_j_lt_i.for_each([&](auto s_ij) {
				const std::size_t j_idx = get_index<'j'>(s_ij);
				w -= A.template at<'i', 'j'>(i_idx, j_idx) *
				     y.template at<'i'>(j_idx);
			});
		}

		y[s_i] = w;
	});

	// Backward substitution: solve Ux = y
	//
	// for (i = N-1; i >= 0; i--) {
	//   w = y[i];
	//   for (j = i+1; j < N; j++)
	//     w -= A[i][j] * x[j];
	//   x[i] = w / A[i][i];
	// }
	//
	// Implemented with an ascending traversal over an "inverse"
	// index inv = 0..N-1, i = N-1-inv, so that we keep using
	// Noarr's natural forward traversal on 'i'.
	// As in the forward pass, we use a slice on 'j' to restrict
	// it to (i, N) and avoid branches inside the loop.

	noarr::traverser(x, y, A).template for_dims<'i'>([&](auto trav_inv) {
		auto s_inv = trav_inv.state();
		const std::size_t inv = get_index<'i'>(s_inv);
		const std::size_t i_idx = n - 1 - inv;

		num_t w = y.template at<'i'>(i_idx);

		const std::size_t first_j = i_idx + 1;
		if (first_j < n) {
			auto trav_j_gt_i =
				trav_inv.order(noarr::slice<'j'>(first_j, n - first_j));

			trav_j_gt_i.for_each([&](auto s_ij) {
				const std::size_t j_idx = get_index<'j'>(s_ij);
				w -= A.template at<'i', 'j'>(i_idx, j_idx) *
				     x.template at<'i'>(j_idx);
			});
		}

		x.template at<'i'>(i_idx) =
			w / A.template at<'i', 'j'>(i_idx, i_idx);
	});
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// Problem size
	std::size_t n = N;

	// Structures and bags
	auto set_len_i = noarr::set_length<'i'>(n);
	auto set_len_ij = set_len_i ^ noarr::set_length<'j'>(n);

	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_len_ij);
	auto b = noarr::bag(noarr::scalar<num_t>() ^ tuning.vec_layout ^ set_len_i);
	auto x = noarr::bag(noarr::scalar<num_t>() ^ tuning.vec_layout ^ set_len_i);
	auto y = noarr::bag(noarr::scalar<num_t>() ^ tuning.vec_layout ^ set_len_i);

	// Initialize data
	init_array(static_cast<int>(n),
	           A.get_ref(), b.get_ref(), x.get_ref(), y.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// Run kernel
	kernel_ludcmp(A.get_ref(), b.get_ref(), x.get_ref(), y.get_ref());

	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// Output result to stderr (for DCE / checking)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, x.get_ref());
	}

	// Output timing to stdout
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;

	return 0;
}
