#include <chrono>
#include <iomanip>
#include <iostream>

#include <noarr/traversers.hpp>
#include <noarr/structures_extended.hpp> // for fix/slice/rename/bcast/hoist/...
#include <noarr/structures/interop/serialize_data.hpp>

#include "defines.hpp"
#include "ludcmp.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();

struct tuning {
	// A: i x j
	DEFINE_PROTO_STRUCT(a_layout, j_vec ^ i_vec);
	// 1D vectors (b, x, y): i
	DEFINE_PROTO_STRUCT(vec_layout, i_vec);
} tuning;

// Array initialization
void init_array(int n, auto A, auto b, auto x, auto y) {
	using namespace noarr;

	num_t fn = static_cast<num_t>(n);

	// Initialize x, y, b
	// for (i = 0; i < n; i++) {
	//   x[i] = 0;
	//   y[i] = 0;
	//   b[i] = (i+1)/fn/2.0 + 4;
	// }
	traverser(b, x, y).for_each([=](auto state) {
		auto i = get_index<'i'>(state);

		x[state] = num_t(0);
		y[state] = num_t(0);

		x[state]; // keep structure usage symmetrical
		y[state];

		b[state] = (static_cast<num_t>(i + 1) / fn / num_t(2.0)) + num_t(4);
	});

	// Initialize A:
	// for (i = 0; i < n; i++) {
	//   for (j = 0; j <= i; j++)
	//     A[i][j] = (DATA_TYPE)(-j % n) / n + 1;
	//   for (j = i+1; j < n; j++)
	//     A[i][j] = 0;
	//   A[i][i] = 1;
	// }
	// Rewritten as a single 2D traversal with case distinction on j vs i.
	traverser(A).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);

		if (j < i) {
			// (DATA_TYPE)(-j % n) / n + 1;
			int nn = n;
			int jj = static_cast<int>(j);
			int rem = (-jj) % nn;
			A[state] = static_cast<num_t>(rem) / fn + num_t(1);
		} else if (j == i) {
			A[state] = num_t(1);
		} else {
			A[state] = num_t(0);
		}
	});

	// Make the matrix positive semi-definite:
	// B[r][s] = 0
	// for (t = 0; t < n; ++t)
	//   for (r = 0; r < n; ++r)
	//     for (s = 0; s < n; ++s)
	//       B[r][s] += A[r][t] * A[s][t];
	// A[r][s] = B[r][s]

	// B has the same structure as A
	auto B = noarr::bag(A.structure());

	// Zero out B
	traverser(B).for_each([&](auto state) {
		B[state] = num_t(0);
	});

	// Create views:
	// A_rt: A[r][t]
	auto A_rt = A.get_ref() ^ noarr::rename<'i', 'r', 'j', 't'>();
	// A_st: A[s][t]
	auto A_st = A.get_ref() ^ noarr::rename<'i', 's', 'j', 't'>();
	// B_rs: B[r][s]
	auto B_rs = B.get_ref() ^ noarr::rename<'i', 'r', 'j', 's'>();
	// B_rst: B[r][s] broadcast over t
	auto B_rst = B_rs ^ noarr::bcast<'t'>(n);

	// Accumulate B[r][s] += A[r][t] * A[s][t]
	noarr::traverser(B_rst, A_rt, A_st)
		.order(noarr::hoist<'t'>())
		.for_each([&](auto state) {
			B_rst[state] += A_rt[state] * A_st[state];
		});

	// Copy B back into A: A[r][s] = B[r][s]
	noarr::traverser(A, B).for_each([&](auto state) {
		A[state] = B[state];
	});
}

// Main computational kernel
//
// All loop nests are expressed using Noarr traversers. Inner “k”-loops
// are implemented as 1D traversals over sliced views to keep memory
// access explicit and regular, while preserving the original arithmetic
// order.
[[gnu::flatten, gnu::noinline]]
void kernel_ludcmp(auto A, auto b, auto x, auto y) {
	using namespace noarr;

	// Work with reference bags so that we can freely create views (^ fix/rename/slice)
	auto A_ref = A.get_ref();
	auto b_ref = b.get_ref();
	auto x_ref = x.get_ref();
	auto y_ref = y.get_ref();

	// 1D views of x and y re-indexed by 'j' (used in dot products below)
	auto x_as_j = x_ref ^ rename<'i', 'j'>();
	auto y_as_j = y_ref ^ rename<'i', 'j'>();

	// Length in the 'i' dimension
	std::size_t n = A_ref | get_length<'i'>();

	// ------------------------------------------------------------------
	// LU factorization (Doolittle-like scheme)
	//
	// Original:
	// for (i = 0; i < N; i++) {
	//   for (j = 0; j < i; j++) {
	//     w = A[i][j];
	//     for (k = 0; k < j; k++)
	//       w -= A[i][k] * A[k][j];
	//     A[i][j] = w / A[j][j];
	//   }
	//   for (j = i; j < N; j++) {
	//     w = A[i][j];
	//     for (k = 0; k < i; k++)
	//       w -= A[i][k] * A[k][j];
	//     A[i][j] = w;
	//   }
	// }
	//
	// We keep the same computation, but express the inner k-loop as a
	// 1D traversal over the i-th row, sliced to 0..max_k-1. For each k
	// we read:
	//   row_i[j_idx = k] == A[i][k]   (contiguous in memory)
	//   A_ref(i = k, j = j_idx) == A[k][j]
	// This preserves arithmetic order and improves locality along rows.
	// ------------------------------------------------------------------
	traverser(A_ref).template for_dims<'i'>([&](auto trav_i) {
		auto s_i = trav_i.state();
		std::size_t i_idx = get_index<'i'>(s_i);

		// View of the current row i: only 'j' dimension remains.
		auto row_i = A_ref ^ fix<'i'>(i_idx);

		trav_i.for_each([&](auto s_ij) {
			std::size_t j_idx = get_index<'j'>(s_ij);

			num_t w = A_ref[s_ij];

			std::size_t max_k = (j_idx < i_idx) ? j_idx : i_idx;

			if (max_k > 0) {
				// Traverse k = 0..max_k-1 as j-indices in row_i.
				traverser(row_i)
					.order(slice<'j'>(0, max_k))
					.for_each([&](auto s_k) {
						std::size_t k_idx = get_index<'j'>(s_k);

						// row_i[s_k]   == A[i_idx][k_idx]
						// A_ref(i=k,j) == A[k_idx][j_idx]
						w -= row_i[s_k] *
						     A_ref.template at<'i', 'j'>(k_idx, j_idx);
					});
			}

			if (j_idx < i_idx) {
				// Strictly lower part: divide by pivot on the diagonal
				A_ref[s_ij] = w / A_ref.template at<'i', 'j'>(j_idx, j_idx);
			} else {
				// Upper part (including diagonal): store w directly
				A_ref[s_ij] = w;
			}
		});
	});

	// ------------------------------------------------------------------
	// Forward substitution: solve Ly = b
	//
	// Original:
	// for (i = 0; i < N; i++) {
	//   w = b[i];
	//   for (j = 0; j < i; j++)
	//     w -= A[i][j] * y[j];
	//   y[i] = w;
	// }
	//
	// We again express the inner j-loop as a 1D traversal over the
	// i-th row and the first i elements of y, sharing the same 'j'
	// index, sliced to [0, i).
	// ------------------------------------------------------------------
	traverser(y_ref, b_ref).template for_dims<'i'>([&](auto trav_i) {
		auto s_i = trav_i.state();
		std::size_t i_idx = get_index<'i'>(s_i);

		num_t w = b_ref[s_i];

		if (i_idx > 0) {
			// L's row i: A[i][0..i-1]
			auto row_i = A_ref ^ fix<'i'>(i_idx);

			// y_as_j: y[j] re-indexed as 'j'
			traverser(row_i, y_as_j)
				.order(slice<'j'>(0, i_idx)) // j = 0..i-1
				.for_each([&](auto s_j) {
					w -= row_i[s_j] * y_as_j[s_j];
				});
		}

		y_ref[s_i] = w;
	});

	// ------------------------------------------------------------------
	// Backward substitution: solve Ux = y
	//
	// Original:
	// for (i = N-1; i >= 0; i--) {
	//   w = y[i];
	//   for (j = i+1; j < N; j++)
	//     w -= A[i][j] * x[j];
	//   x[i] = w / A[i][i];
	// }
	//
	// Implemented using an ascending traversal over an "inverse" index:
	//   inv = 0..N-1, i = N-1-inv
	// The inner j-loop is expressed as a 1D traversal over the slice
	// j = i+1..N-1 of the i-th row and x[j].
	// ------------------------------------------------------------------
	traverser(x_ref, y_ref).template for_dims<'i'>([&](auto trav_inv) {
		auto s_inv = trav_inv.state();
		std::size_t inv = get_index<'i'>(s_inv);
		std::size_t i_idx = n - 1 - inv;

		num_t w = y_ref.template at<'i'>(i_idx);

		if (i_idx + 1 < n) {
			// U's row i: A[i][i+1..N-1]
			auto row_i = A_ref ^ fix<'i'>(i_idx);

			// x_as_j: x[j] re-indexed as 'j'
			std::size_t start_j = i_idx + 1;
			std::size_t len_j   = n - start_j;

			traverser(row_i, x_as_j)
				.order(slice<'j'>(start_j, len_j)) // j = i+1..N-1
				.for_each([&](auto s_j) {
					w -= row_i[s_j] * x_as_j[s_j];
				});
		}

		x_ref.template at<'i'>(i_idx) =
			w / A_ref.template at<'i', 'j'>(i_idx, i_idx);
	});
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// Problem size
	std::size_t n = N;

	// Structures and bags
	auto set_len_i = noarr::set_length<'i'>(n);
	auto set_len_ij = set_len_i ^ noarr::set_length<'j'>(n);

	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_len_ij);
	auto b = noarr::bag(noarr::scalar<num_t>() ^ tuning.vec_layout ^ set_len_i);
	auto x = noarr::bag(noarr::scalar<num_t>() ^ tuning.vec_layout ^ set_len_i);
	auto y = noarr::bag(noarr::scalar<num_t>() ^ tuning.vec_layout ^ set_len_i);

	// Initialize data
	init_array(static_cast<int>(n),
	           A.get_ref(), b.get_ref(), x.get_ref(), y.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// Run kernel
	kernel_ludcmp(A.get_ref(), b.get_ref(), x.get_ref(), y.get_ref());

	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// Output result to stderr (for DCE / checking)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, x.get_ref());
	}

	// Output timing to stdout
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;

	return 0;
}
